857	// An inline cache for a namedtuple field read: the top bit tags the value (an instance-attribute index, the
858	// cache's other use, never has it), the low NTF_IDX_BITS bits are the field's index in the wrapped tuple, and
859	// the bits between are the CLASS_EPOCH when it was filled. A change to
860	// any class's dict (P.x = property(...)) bumps the epoch, so the next hit misses and getattr honours the new
861	// descriptor. Only the lower 64 - NTF_IDX_BITS - 1 epoch bits are kept: the epoch never decreases, so a hit
862	// is still only possible on the exact epoch that filled it, and after 2^(64 - NTF_IDX_BITS - 1) class
863	// changes the tag stops hitting (reads stay correct, just take the general path).
864	const NTF_IDX_BITS: u32 = 24;
865	const NTF_IDX_MASK: usize = (1 << NTF_IDX_BITS) - 1;
866	const NTF_TAG: usize = 1 << (usize::BITS - 1);
867	const NTF_EP_MASK: usize = (NTF_TAG - 1) >> NTF_IDX_BITS;
868	#[inline]
869	fn ntf_ic(i: usize, ep: u64) -> usize {
870	    NTF_TAG | (((ep as usize) & NTF_EP_MASK) << NTF_IDX_BITS) | i
871	}
